# Отбор задач листка 29.09 по методу Р183: карточка -> фильтры -> покрытие -> состав
from itertools import combinations
import json
def dig(d): return [x for x in range(10,100) if str(d) in str(x)]
def mult(k): return [x for x in range(10,100) if x%k==0]
def coins(S): return [(z,y,S-5*z-2*y) for z in range(S//5,-1,-1) for y in range((S-5*z)//2,-1,-1)]
def prods(L): return sorted({a*b for a in L for b in L})
def cells_frame(n,k): return n*n-k*k
def spichki(m,n): return m*(n+1)+n*(m+1)
def show_coins(r): return ", ".join("+".join(["5"]*z+["2"]*y+["1"]*x) for z,y,x in r)
C=[]
def card(**k): C.append(k)
