IDEI={'T1':'прямоугольник клеток = умножение','T2':'таблица из цифр (разряды — оси)','T3':'±1 при построении (линии против клеток)',
 'T4':'сумма нескольких таблиц разного размера','T5':'линия в таблице (диагональ, одна сумма цифр)',
 'V1':'дополнение: всё минус лишнее','V2':'включение-исключение: пересечение вычесть',
 'S1':'разбиение на непересекающиеся группы','P1':'перебор в заданном порядке, один уровень','P2':'перебор в заданном порядке, два уровня'}
MAP={'K01':['T1'],'K02':['T2','V1'],'K03':['T1','S1'],'K04':['T3','T4','S1'],'K05':['T3'],'K06':['T2'],'K07':['S1','T1'],
 'K08':['T2','V1'],'K09':['T1','V1','S1'],'K10':['P2','S1'],'K11':['P1'],'K12':['P1'],'K13':['V2','T2'],'K14':['P1','S1'],'K15':['V2'],'K16':['P1','T5']}
for c in C: c['idea']=MAP[c['id']]
# ---------- фильтры ----------
F={}
for c in C:
    f={}
    f['F1 вершина ядра']=bool(c['v'])
    f['F2 нет запрещённого']=c['forb'] is None
    f['F4 время ○≤4 мин']=c['t'][0]<=4
    f['F6 не повтор']=not (c['repeat'] or '').startswith('ПОВТОР')
    f['F7 рассуждение → только △']=not c['reason']
    f['F8 не тривиально (≥1 мин)']=c['t'][0]>=1
    F[c['id']]=f
json.dump({'C':C,'F':F},open('otbor.json','w'),ensure_ascii=False,indent=1)
for c in C: print(c['id'],c['ans'],'|',{k:v for k,v in F[c['id']].items() if not v})

# ---------- покрытие (Р176, Р180, Р182) ----------
NEW={'T','P'}; OLD={'S','V'}
def ok_for_circle(c): f=F[c['id']]; return all(f.values())
pool=[c for c in C if ok_for_circle(c)]
chosen=[]; seen=set()
# жадно: сначала входы и новые вершины; одна ступень = хотя бы одна НОВАЯ идея
vertex=lambda c: {i[0] for i in c['idea']}
T=lambda i: next(x for x in C if x['id']==i)
# КРУЖКИ: жадное покрытие целевых идей Z; фиксировано решением владельца K08 (Р184); ключ — новые идеи из Z на минуту;
# ничья — у кого есть выход в сторону (картинка), затем меньшее время; бюджет ≤ 10 пунктов
Z={'T1','T2','T3','T4','P1','P2','S1','V1'}
FIX=['K08']; chosen=list(FIX); seen=set(); [seen.update(T(i)['idea']) for i in FIX]
while Z-seen:
    cand=[c for c in C if c['id'] not in chosen and ok_for_circle(c) and (set(c['idea'])&(Z-seen))]
    best=max(cand,key=lambda c:(len(set(c['idea'])&(Z-seen))/c['t'][0],len(set(c['idea'])&(Z-seen)),'картинк' in c['txt'].lower(),-c['t'][0]))
    chosen.append(best['id']); seen|=set(best['idea'])
assert sum(T(i)['pts'] for i in chosen)<=10
# ТРЕУГОЛЬНИКИ: 3 задачи не из кружков, ≥2 вершины, ≤5 мин; сначала V2 (вкл.-искл. в кружках нет), затем максимум новых идей,
# ничья — другая «вселенная», чем у задач кружков (не таблица цифр), затем меньшее время
rest=[c for c in C if c['id'] not in chosen and len(vertex(c))>=2 and c['t'][0]<=5 and F[c['id']]['F2 нет запрещённого'] and F[c['id']]['F6 не повтор']]
tri=[]; ti=set()
for _ in range(3):
    best=max((c for c in rest if c['id'] not in tri),key=lambda c:('V2' in c['idea'] and 'V2' not in ti,len(set(c['idea'])-ti),'T2' not in c['idea'],-c['pts'],-c['t'][0]))
    tri.append(best['id']); ti|=set(best['idea'])
cov={v:[i for i in chosen for vv in next(x for x in C if x['id']==i)['v'] if vv==v] for v in 'TPSV'}
print('КРУЖКИ:',chosen,'пунктов',sum(next(x for x in C if x['id']==i)['pts'] for i in chosen))
print('покрытие:',cov,' новые ≥2:',all(len(cov[v])>=2 for v in NEW),' старые ≥1:',all(len(cov[v])>=1 for v in OLD))
print('время кружков (подг./медл.):',sum(next(x for x in C if x['id']==i)['t'][0] for i in chosen),sum(next(x for x in C if x['id']==i)['t'][1] for i in chosen))
u=set(v for i in tri for v in next(x for x in C if x['id']==i)['v'])
print('ТРЕУГОЛЬНИКИ:',tri,'вершины:',u,'все четыре:',u=={'T','P','S','V'},' каждый ≥2:',all(len(next(x for x in C if x['id']==i)['v'])>=2 for i in tri))
json.dump({'C':C,'F':F,'krug':chosen,'tri':tri},open('otbor.json','w'),ensure_ascii=False,indent=1)
